                g = low[b] * p
                ok = True
                for c in range(b + 1, 15):
                    prev_p = pow_arr[14 - c]
                    base = low[c] * prev_p
                    if g * pow2[c - b] > base + pow2[c] - 1:
                        ok = False
                        break
                if ok:
                    pow_arr[i] = p
                    low[b] = (g + n - 1) // p if p else 0
