from math import gcd

class Solution:
    def resilientSubarray(self, nums: list[int], k: int) -> int:
        ans = 0
        n = len(nums)
        i = 0
        while i < n:
            r = nums[i] % k
            j = i
            while j < n and nums[j] % k == r:
                j += 1
            L = j - i
            if r == 0:
                cand = L
            else:
                d = k // gcd(r, k)
                cand = 1 + d * ((L - 1) // d)
            if cand > ans:
                ans = cand
            i = j
        return ans

