class Solution:
    def longestSubarray(self, nums: list[int], k: int) -> int:
        n = len(nums)
        ans = 0

        k_odd = (k % 2 == 1)
        inv2 = (k + 1) // 2 if k_odd else 0  # 2 * inv2 == 1 (mod k) for odd k
        half = k // 2

        for i in range(n):
            total = 0
            cnt = {}

            for j in range(i, n):
                x = nums[j]
                total += x
                r = total % k

                xr = x % k
                cnt[xr] = cnt.get(xr, 0) + 1

                length = j - i + 1

                # Already divisible by k.
                if r == 0:
                    if length > ans:
                        ans = length
                    continue

                # Need an element y in nums[i..j] with:
                # total - 2*y == 0 (mod k)  <=>  2*y == r (mod k)
                if k_odd:
                    need = (r * inv2) % k
                    if cnt.get(need, 0):
                        ans = max(ans, length)
                else:
                    # 2*y == r (mod k) has solutions only when r is even.
                    if (r & 1) == 0:
                        base = r // 2  # modulo k/2
                        if cnt.get(base, 0) or cnt.get(base + half, 0):
                            ans = max(ans, length)

        return ans

class Solution:
    def longestSubarray(self, nums, k):
        n = len(nums)
        # prefix sums mod k
        P = [0] * (n + 1)
        s = 0
        for i, x in enumerate(nums):
            s = (s + x) % k
            P[i + 1] = s

        NEG = -10**9
        fc = [-1] * k      # first j in [0,n] with P[j] == c
        lc = [NEG] * k     # last  j in [0,n] with P[j] == c
        for j in range(n + 1):
            r = P[j]
            if fc[r] == -1:
                fc[r] = j
            lc[r] = j

        # Condition A: subarray sum already divisible by k  (P[l] == P[r+1])
        ans = 0
        for c in range(k):
            if fc[c] != -1 and lc[c] > fc[c]:
                v = lc[c] - fc[c]
                if v > ans:
                    ans = v

        # Condition B: negate element i in [l,r]; need
        #   P[r+1] - P[l] == w_i (mod k),  w_i = 2*nums[i] mod k.
        # For left residue c and witness residue a, right residue d = (a+c)%k.
        # Best window: l = fc[c], r = lc[d]-1, feasible iff some i in
        # [fc[c], lc[d]-1] has w_i == a.  Length = lc[d] - fc[c].
        w = [(2 * x) % k for x in nums]

        res_by_fc = {}
        for c in range(k):
            f = fc[c]
            if f != -1 and f <= n - 1:
                res_by_fc.setdefault(f, []).append(c)

        # candidate right-residues d, ordered by lc[d] descending
        dsorted = [d for d in range(k) if lc[d] != NEG]
        dsorted.sort(key=lambda d: -lc[d])

        SENT = n + 1
        cur = [SENT] * k   # cur[a] = first i >= pos with w_i == a
        best_B = 0
        lc_l = lc
        cur_l = cur
        ds_l = dsorted
        for pos in range(n - 1, -1, -1):
            cur_l[w[pos]] = pos
            lst = res_by_fc.get(pos)
            if lst is not None:
                for c in lst:
                    fcc = fc[c]
                    for d in ds_l:
                        ld = lc_l[d]
                        if ld - fcc <= best_B:
                            break
                        a = d - c
                        if a < 0:
                            a += k
                        if cur_l[a] <= ld - 1:
                            v = ld - fcc
                            if v > best_B:
                                best_B = v
                            break
        return ans if ans > best_B else best_B

