class Solution:
    def longestSubarray(self, nums: list[int], k: int) -> int:
        # Precompute the smallest prime factor (spf) for numbers up to max(nums) 
        # using a linear sieve or standard sieve. Here we use a linear sieve.
        max_val = max(nums)
        spf = list(range(max_val + 1))

        for i in range(2, int(max_val**0.5) + 1):
            if spf[i] == i: # i is a prime
                for j in range(i * i, max_val + 1, i):
                    if spf[j] == j:
                        spf[j] = i

        # Sliding window
        counts = {}
        left = 0
        res = 0

        for right in range(len(nums)):
            # Factorize the incoming number using spf
            curr = nums[right]
            while curr > 1:
                p = spf[curr]
                counts[p] = counts.get(p, 0) + 1
                # Increment frequency and completely divide it out of curr
                while curr % p == 0:
                    curr //= p

            # Shrink the window if we exceed K distinct prime factors
            while len(counts) > k:
                outgoing = nums[left]
                while outgoing > 1:
                    p = spf[outgoing]
                    counts[p] -= 1
                    if counts[p] == 0:
                        del counts[p]
                    # Decrement frequency and completely divide it out of outgoing
                    while outgoing % p == 0:
                        outgoing //= p
                left += 1

            # Record and maximize the valid window length
            res = max(res, right - left + 1)

        return res

class Solution:
    def maxSubarray(self, nums: list[int]) -> int:
        V = 500
        cnt = [0] * (V + 1)
        bad = 0
        left = 0
        ans = 0

        def target_pairs(x: int) -> int:
            total = 0
            for a in range(1, x // 2 + 1):
                b = x - a
                if a == b:
                    c = cnt[a]
                    total += c * (c - 1) // 2
                else:
                    total += cnt[a] * cnt[b]
            return total

        def add(x: int) -> None:
            nonlocal bad
            delta = target_pairs(x)
            for y in range(1, V - x + 1):
                delta += cnt[y] * cnt[x + y]
            cnt[x] += 1
            bad += delta

        def remove(x: int) -> None:
            nonlocal bad
            old = cnt[x]
            delta = target_pairs(x)
            for y in range(1, V - x + 1):
                if y == x:
                    delta += (old - 1) * cnt[x + y]
                else:
                    delta += cnt[y] * cnt[x + y]
            cnt[x] -= 1
            bad -= delta

        for right, x in enumerate(nums):
            add(x)
            while bad > 0:
                remove(nums[left])
                left += 1
            ans = max(ans, right - left + 1)

        return ans

