class Solution:
    def maxValidSplits(self, nums: list[int]) -> int:
        n = len(nums)

        def count_splits(arr):
            m = len(arr)
            if m < 2:
                return 0
            pre = [0] * m
            suf = [0] * m
            g = 0
            for i in range(m):
                g = gcd(g, arr[i])
                pre[i] = g
            g = 0
            for i in range(m - 1, -1, -1):
                g = gcd(g, arr[i])
                suf[i] = g
            cnt = 0
            for i in range(m - 1):
                if pre[i] == suf[i + 1]:
                    cnt += 1
            return cnt

        best = count_splits(nums)
        for r in range(n):
            arr = nums[:r] + nums[r + 1:]
            c = count_splits(arr)
            if c > best:
                best = c
        return best

class Solution:
    def maximumValue(self, n: int, s: int, m: int) -> int:
        if n == 1:
            return s

        # The best pattern starts by increasing.  Its first peak is s + m.
        # After each peak P, the next value must be at most P - 1 (strict
        # integer decrease), so the next peak is at most (P - 1) + m.
        # Thus every additional pair of positions increases the best peak
        # by m - 1.  There are floor(n / 2) peaks, hence the formula below.
        return s + m + (n // 2 - 1) * (m - 1)

