class Solution:
    def minOperations(self, nums: list[int]) -> int:
        total = 0
        for n in nums:
            arr = _EVEN if n % 2 == 0 else _ODD
            i = bisect_left(arr, n)
            best = float('inf')
            if i < len(arr):
                best = arr[i] - n
            if i > 0:
