                    cur = dp[t]
                    if (cur is None
                            or cand[0] < cur[0]
                            or (cand[0] == cur[0] and cand[1] < cur[1])):
                        dp[t] = cand

        # Largest achievable sum <= s (must be a non-empty subset)
        for t in range(s, 0, -1):
            if dp[t] is not None:
                return list(dp[t][1])
        return []

from collections import Counter


class Solution:
    def rearrangeArray(self, nums: list[int]) -> list[int]:
        count = Counter(nums)
        ans = []
        remaining = len(nums)
        while remaining > 0:
            for v in sorted(count):
                if count[v] > 0:
                    ans.append(v)
                    count[v] -= 1
                    remaining -= 1
        return ans

